def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([100]), fmt([0, 100]), fmt([50, 50]), fmt([70, 70, 70]), fmt([0, 100, 33, 33, 1, 2, 100]), fmt(list(range(0, 101)))]
    for n in range(2, 30):
        hi = rng.choice([3, 10, 100])
        tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 100) for _ in range(1000)]))
    tests.append(fmt([rng.randint(0, 100) for _ in range(100000)]))
    tests.append(fmt([rng.choice([0, 100]) for _ in range(100000)]))
    tests.append(fmt([rng.randint(40, 60) for _ in range(100000)]))
    tests.append(fmt([100] * 100000))
    return tests

